CREATE FUNCTION public.admin_membership_summary() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN (SELECT jsonb_build_object('total',count(*),'pending',count(*) FILTER(WHERE application_status='Pending'),'approved',count(*) FILTER(WHERE application_status='Approved'),'rejected',count(*) FILTER(WHERE application_status='Rejected'),'universities',count(DISTINCT university),'states',count(DISTINCT state),'applicants',count(*) FILTER(WHERE application_status<>'Approved'),'awaiting',count(*) FILTER(WHERE application_status='Approved' AND m.onboarded_at IS NULL),'onboarded',count(*) FILTER(WHERE application_status='Approved' AND m.onboarded_at IS NOT NULL),'universityOptions',coalesce(jsonb_agg(DISTINCT university),'[]'::jsonb),'stateOptions',coalesce(jsonb_agg(DISTINCT state),'[]'::jsonb)) FROM public.applications a LEFT JOIN public.membership_management m ON m.application_id=a.id); END $$;
REVOKE ALL ON FUNCTION public.admin_membership_summary() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_membership_summary() TO authenticated;
CREATE FUNCTION public.registration_closed_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.registration_is_open() THEN RAISE EXCEPTION 'Registration is currently closed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER registration_open_guard BEFORE INSERT ON public.pending_registrations FOR EACH ROW EXECUTE FUNCTION public.registration_closed_guard();